import { Card, CardBody, CardTitle, Container, Row, Col } from "reactstrap";
import { useEffect, useState } from "react";
import { db } from "../../firebase"; 
import { collection, getDocs, doc, getDoc } from "firebase/firestore";

const Header = () => {
  const [carbonData, setCarbonData] = useState({
    footprint: 0,
    credits: 0,
    progress: 0,
    rank: 0,
  });

  const [previousData, setPreviousData] = useState({
    footprint: 0,
    credits: 0,
    progress: 0,
  });

  useEffect(() => {
    const fetchAverageCarbonData = async () => {
      try {
        const querySnapshot = await getDocs(collection(db, "carbonFootprint"));
        const data = querySnapshot.docs.map(doc => doc.data());

        if (data.length === 0) return; // No data found, prevent division by zero

        // Fetch previous average from Firestore (if stored)
        const previousDocRef = doc(db, "carbonFootprint", "previousData");
        const previousDocSnap = await getDoc(previousDocRef);

        if (previousDocSnap.exists()) {
          setPreviousData(previousDocSnap.data());
        }

        // Calculate Averages
        const totalEntries = data.length;
        const avgFootprint = data.reduce((sum, d) => sum + parseFloat(d.totalCarbon || 0), 0) / totalEntries;
        const avgCredits = data.reduce((sum, d) => sum + parseFloat(d.credits || 0), 0) / totalEntries;
        const avgProgress = data.reduce((sum, d) => sum + parseFloat(d.progress || 0), 0) / totalEntries;

        setCarbonData({
          footprint: avgFootprint.toFixed(2),
          credits: avgCredits.toFixed(2),
          progress: avgProgress.toFixed(2),
          rank: Math.floor(Math.random() * 100), // Random rank (can be updated with real logic)
        });

      } catch (error) {
        console.error("Error fetching data:", error);
      }
    };

    fetchAverageCarbonData();
  }, []);

  // Function to determine arrow icon and color
  const getArrowIcon = (current, previous) => {
    if (current > previous) {
      return { icon: "fas fa-arrow-up", color: "success" };
    } else if (current < previous) {
      return { icon: "fas fa-arrow-down", color: "danger" };
    } else {
      return { icon: "fas fa-minus", color: "muted" }; // No change
    }
  };

  return (
    <div className="header bg-gradient-info pb-8 pt-5 pt-md-8">
      <Container fluid>
        <div className="header-body">
          <Row>
            {/* Carbon Footprint */}
            <Col lg="6" xl="3">
              <Card className="card-stats mb-4 mb-xl-0">
                <CardBody>
                  <Row>
                    <div className="col">
                      <CardTitle tag="h5" className="text-uppercase text-muted mb-0">
                        Avg Carbon Footprint (kg CO₂)
                      </CardTitle>
                      <span className="h2 font-weight-bold mb-0">{carbonData.footprint}</span>
                    </div>
                    <Col className="col-auto">
                      <div className="icon icon-shape bg-danger text-white rounded-circle shadow">
                        <i className="fas fa-chart-bar" />
                      </div>
                    </Col>
                  </Row>
                  <p className="mt-3 mb-0 text-muted text-sm">
                    <span className={`text-${getArrowIcon(carbonData.footprint, previousData.footprint).color} mr-2`}>
                      <i className={getArrowIcon(carbonData.footprint, previousData.footprint).icon} /> 
                      {Math.abs(carbonData.footprint - previousData.footprint).toFixed(2)} kg
                    </span>{" "}
                    <span className="text-nowrap">Since last update</span>
                  </p>
                </CardBody>
              </Card>
            </Col>

            {/* Carbon Credits Earned */}
            <Col lg="6" xl="3">
              <Card className="card-stats mb-4 mb-xl-0">
                <CardBody>
                  <Row>
                    <div className="col">
                      <CardTitle tag="h5" className="text-uppercase text-muted mb-0">
                        Avg Carbon Credits
                      </CardTitle>
                      <span className="h2 font-weight-bold mb-0">{carbonData.credits}</span>
                    </div>
                    <Col className="col-auto">
                      <div className="icon icon-shape bg-warning text-white rounded-circle shadow">
                        <i className="fas fa-chart-pie" />
                      </div>
                    </Col>
                  </Row>
                  <p className="mt-3 mb-0 text-muted text-sm">
                    <span className={`text-${getArrowIcon(carbonData.credits, previousData.credits).color} mr-2`}>
                      <i className={getArrowIcon(carbonData.credits, previousData.credits).icon} /> 
                      {Math.abs(carbonData.credits - previousData.credits).toFixed(2)}
                    </span>{" "}
                    <span className="text-nowrap">Since last update</span>
                  </p>
                </CardBody>
              </Card>
            </Col>

            {/* Carbon Reduction Progress */}
            <Col lg="6" xl="3">
              <Card className="card-stats mb-4 mb-xl-0">
                <CardBody>
                  <Row>
                    <div className="col">
                      <CardTitle tag="h5" className="text-uppercase text-muted mb-0">
                        Avg Carbon Progress (%)
                      </CardTitle>
                      <span className="h2 font-weight-bold mb-0">{carbonData.progress}</span>
                    </div>
                    <Col className="col-auto">
                      <div className="icon icon-shape bg-yellow text-white rounded-circle shadow">
                        <i className="fas fa-users" />
                      </div>
                    </Col>
                  </Row>
                  <p className="mt-3 mb-0 text-muted text-sm">
                    <span className={`text-${getArrowIcon(carbonData.progress, previousData.progress).color} mr-2`}>
                      <i className={getArrowIcon(carbonData.progress, previousData.progress).icon} /> 
                      {Math.abs(carbonData.progress - previousData.progress).toFixed(2)}%
                    </span>{" "}
                    <span className="text-nowrap">Since last update</span>
                  </p>
                </CardBody>
              </Card>
            </Col>

            {/* Rank */}
            <Col lg="6" xl="3">
              <Card className="card-stats mb-4 mb-xl-0">
                <CardBody>
                  <Row>
                    <div className="col">
                      <CardTitle tag="h5" className="text-uppercase text-muted mb-0">
                        Rank
                      </CardTitle>
                      <span className="h2 font-weight-bold mb-0">#{carbonData.rank}</span>
                    </div>
                    <Col className="col-auto">
                      <div className="icon icon-shape bg-info text-white rounded-circle shadow">
                        <i className="fas fa-percent" />
                      </div>
                    </Col>
                  </Row>
                </CardBody>
              </Card>
            </Col>
          </Row>
        </div>
      </Container>
    </div>
  );
};

export default Header;
